import { useState, useEffect } from 'react';

function VehicleList({ user: _user, onRent, onViewDetail }) {
  const [vehicles, setVehicles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ ecoOnly: false, minPrice: '', maxPrice: '' });

  useEffect(() => {
    const fetchVehicles = async () => {
      setLoading(true);
      const res = await fetch('http://localhost:3002/api/vehicles');
      const data = await res.json();
      setVehicles(data);
      setLoading(false);
    };
    fetchVehicles();
  }, []);

  if (loading) return <div className="loading">Loading vehicles...</div>;

  const allPrices = vehicles.filter((v) => v.available).map((v) => v.pricePerDay);
  const minAll = allPrices.length ? Math.min(...allPrices) : 0;
  const maxAll = allPrices.length ? Math.max(...allPrices) : 9999;

  const filtered = vehicles
    .filter((v) => v.available)
    .filter((v) => !filters.ecoOnly || v.segment === 'Economy')
    .filter((v) => filters.minPrice === '' || v.pricePerDay >= Number(filters.minPrice))
    .filter((v) => filters.maxPrice === '' || v.pricePerDay <= Number(filters.maxPrice));

  const activeCount =
    (filters.ecoOnly ? 1 : 0) +
    (filters.minPrice !== '' ? 1 : 0) +
    (filters.maxPrice !== '' ? 1 : 0);

  const clearFilters = () => setFilters({ ecoOnly: false, minPrice: '', maxPrice: '' });

  return (
    <div className="vehicle-list">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '20px', flexWrap: 'wrap', gap: '12px' }}>
        <h2 style={{ margin: 0 }}>Available Vehicles</h2>
        <span style={{ fontSize: '14px', color: '#888' }}>
          {filtered.length} of {vehicles.filter((v) => v.available).length} vehicles
        </span>
      </div>

      {/* Filter bar */}
      <div style={{ background: '#fff', border: '1.5px solid #f0f0f0', borderRadius: '14px', padding: '18px 22px', marginBottom: '28px', display: 'flex', alignItems: 'center', gap: '24px', flexWrap: 'wrap', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>

        {/* Eco toggle */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <button
            onClick={() => setFilters((f) => ({ ...f, ecoOnly: !f.ecoOnly }))}
            style={{
              display: 'flex', alignItems: 'center', gap: '7px',
              padding: '8px 16px', borderRadius: '99px', cursor: 'pointer',
              fontWeight: 600, fontSize: '14px', transition: 'all 0.2s',
              border: `2px solid ${filters.ecoOnly ? '#d3101f' : '#e0e0e0'}`,
              background: filters.ecoOnly ? '#fff0f0' : '#fafafa',
              color: filters.ecoOnly ? '#d3101f' : '#666',
            }}
          >
            <span style={{ fontSize: '16px' }}>🌿</span>
            Economy Only
            {filters.ecoOnly && <span style={{ fontSize: '11px', background: '#d3101f', color: '#fff', borderRadius: '99px', padding: '1px 7px' }}>ON</span>}
          </button>
        </div>

        <div style={{ width: '1px', height: '36px', background: '#f0f0f0' }} />

        {/* Price range */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap' }}>
          <span style={{ fontSize: '14px', fontWeight: 600, color: '#444' }}>Daily Price (₺)</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <input
              type="number"
              placeholder={`Min (${minAll})`}
              value={filters.minPrice}
              min={0}
              onChange={(e) => setFilters((f) => ({ ...f, minPrice: e.target.value }))}
              style={{
                width: '100px', padding: '7px 10px', borderRadius: '8px',
                border: `1.5px solid ${filters.minPrice !== '' ? '#d3101f' : '#e0e0e0'}`,
                fontSize: '14px', outline: 'none',
              }}
            />
            <span style={{ color: '#aaa' }}>—</span>
            <input
              type="number"
              placeholder={`Max (${maxAll})`}
              value={filters.maxPrice}
              min={0}
              onChange={(e) => setFilters((f) => ({ ...f, maxPrice: e.target.value }))}
              style={{
                width: '100px', padding: '7px 10px', borderRadius: '8px',
                border: `1.5px solid ${filters.maxPrice !== '' ? '#d3101f' : '#e0e0e0'}`,
                fontSize: '14px', outline: 'none',
              }}
            />
          </div>
        </div>

        {/* Clear */}
        {activeCount > 0 && (
          <>
            <div style={{ width: '1px', height: '36px', background: '#f0f0f0' }} />
            <button
              onClick={clearFilters}
              style={{ background: 'none', border: 'none', color: '#d3101f', fontWeight: 600, fontSize: '14px', cursor: 'pointer', padding: '4px 0' }}
            >
              Clear filters ({activeCount})
            </button>
          </>
        )}
      </div>

      {/* Results */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 20px', color: '#888' }}>
          <div style={{ fontSize: '48px', marginBottom: '16px' }}>🔍</div>
          <p style={{ fontSize: '16px', fontWeight: 600 }}>No vehicles match your filters.</p>
          <button onClick={clearFilters} style={{ marginTop: '12px', background: 'none', border: 'none', color: '#d3101f', fontWeight: 600, cursor: 'pointer', fontSize: '14px' }}>
            Clear filters
          </button>
        </div>
      ) : (
        <div className="vehicle-grid">
          {filtered.map((vehicle) => (
            <div
              key={vehicle.id}
              className="vehicle-card"
              onClick={() => onViewDetail(vehicle)}
              style={{ cursor: 'pointer' }}
            >
              <div className="vehicle-img-wrap">
                {vehicle.image ? (
                  <img
                    src={vehicle.image.startsWith('http') ? vehicle.image : `/images/${vehicle.image}`}
                    alt={`${vehicle.brand} ${vehicle.model}`}
                    className="vehicle-img"
                    onError={(e) => {
                      e.target.style.display = 'none';
                      e.target.nextSibling.style.display = 'flex';
                    }}
                  />
                ) : null}
                <div
                  className="vehicle-img-fallback"
                  style={{ display: vehicle.image ? 'none' : 'flex' }}
                >
                  🚗
                </div>
                {vehicle.segment === 'Economy' && (
                  <div style={{ position: 'absolute', top: '10px', left: '10px', background: '#22c55e', color: '#fff', fontSize: '11px', fontWeight: 700, padding: '3px 10px', borderRadius: '99px', display: 'flex', alignItems: 'center', gap: '4px' }}>
                    🌿 ECO
                  </div>
                )}
              </div>
              <div className="vehicle-card-body">
                <h3>{vehicle.brand} {vehicle.model}</h3>
                <div className="vehicle-details">
                  <span className="badge">{vehicle.segment}</span>
                  <p>📍 {vehicle.campus}</p>
                  <p className="price">₺{vehicle.pricePerDay}/day</p>
                </div>
                <button
                  className="rent-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    onRent(vehicle);
                  }}
                >
                  Rent Now
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default VehicleList;
